CREATE TABLE grammar_exercises (
    id VARCHAR(80) PRIMARY KEY,
    unit_number INT NOT NULL CHECK (unit_number > 0),
    skill VARCHAR(24) NOT NULL DEFAULT 'GRAMMAR',
    title VARCHAR(180) NOT NULL,
    description TEXT NOT NULL,
    exercise_type VARCHAR(24) NOT NULL CHECK (exercise_type IN ('fill_modal', 'identify_function', 'mixed', 'paragraph')),
    sentence_count INT NOT NULL CHECK (sentence_count > 0),
    gap_count INT NOT NULL DEFAULT 0 CHECK (gap_count >= 0),
    difficulty VARCHAR(16) NOT NULL CHECK (difficulty IN ('Easy', 'Medium', 'Hard')),
    max_score INT NOT NULL CHECK (max_score > 0),
    display_order INT NOT NULL,
    word_bank JSONB,
    questions_json JSONB NOT NULL
);

CREATE TABLE grammar_exercise_attempts (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    exercise_id VARCHAR(80) NOT NULL REFERENCES grammar_exercises(id) ON DELETE CASCADE,
    score NUMERIC(8,2) NOT NULL,
    max_score NUMERIC(8,2) NOT NULL,
    attempt_number INT NOT NULL CHECK (attempt_number > 0),
    completed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_grammar_exercise_attempts_user_exercise ON grammar_exercise_attempts(user_id, exercise_id, completed_at DESC);

INSERT INTO grammar_exercises (id, unit_number, title, description, exercise_type, sentence_count, gap_count, difficulty, max_score, display_order, word_bank, questions_json) VALUES
('warm-up-pick-the-modal', 2, 'Warm-Up: Pick the Modal', 'Choose a modal that fits each funny situation.', 'fill_modal', 10, 0, 'Easy', 10, 1,
'["can", "can’t", "could", "may", "might", "must", "mustn’t", "should", "shouldn’t", "have to", "need to", "don’t have to", "would"]'::jsonb,
$$[
{"id":"q1","before":"You’re laughing so hard — you ","after":" have found that joke really funny.","canonicalAnswer":"must","acceptedAnswers":["must","might","may","could"],"function":"certainty/deduction","explanation":"Must is a strong deduction from the laughter; might, may, and could express a less certain possibility."},
{"id":"q2","before":"", "after":" you tell a joke without laughing yourself?","canonicalAnswer":"Can","acceptedAnswers":["can"],"function":"ability","explanation":"Can asks about someone’s ability in general."},
{"id":"q3","before":"It’s the school comedy night, so we ","after":" rehearse before Friday.","canonicalAnswer":"have to","acceptedAnswers":["have to","need to"],"function":"obligation","explanation":"Have to and need to express a necessary preparation."},
{"id":"q4","before":"You ","after":" laugh at someone’s mistake; it’s hurtful.","canonicalAnswer":"shouldn’t","acceptedAnswers":["shouldn’t","mustn’t"],"function":"advice","explanation":"Shouldn’t advises against unkind laughter; mustn’t makes it a prohibition."},
{"id":"q5","before":"The audience is silent — the comedian ","after":" be very nervous.","canonicalAnswer":"must","acceptedAnswers":["must","might","may","could"],"function":"certainty/deduction","explanation":"Must is a strong conclusion from the evidence; the other accepted answers show possibility."},
{"id":"q6","before":"I’m not sure if the show is funny, but it ","after":" be worth watching.","canonicalAnswer":"might","acceptedAnswers":["might","may","could"],"function":"probability/possibility","explanation":"Might, may, and could all express an uncertain possibility here."},
{"id":"q7","before":"When I was younger, I ","after":" tell jokes for hours.","canonicalAnswer":"could","acceptedAnswers":["could"],"function":"ability","explanation":"Could describes general ability in the past."},
{"id":"q8","before":"You ","after":" come to the show if you’re busy — it’s optional.","canonicalAnswer":"don’t have to","acceptedAnswers":["don’t have to","don’t need to","needn’t"],"function":"no obligation","explanation":"Don’t have to means coming is not necessary; it does not mean you are forbidden."},
{"id":"q9","before":"", "after":" I ask you a funny question?","canonicalAnswer":"Can","acceptedAnswers":["can","could"],"function":"permission","explanation":"Can asks permission informally; could is a more polite alternative. May would sound overly formal here."},
{"id":"q10","before":"She’s laughing at nothing — she ","after":" be watching a comedy on her phone.","canonicalAnswer":"must","acceptedAnswers":["must","might","may","could"],"function":"certainty/deduction","explanation":"Must is a strong deduction; might, may, and could make it a possibility instead."}
]$$::jsonb),
('what-is-the-modal-doing', 2, 'What Is the Modal Doing?', 'Read the modal in context and choose its function.', 'identify_function', 10, 0, 'Easy', 10, 2, NULL,
$$[
{"id":"q1","sentence":"You must have laughed a lot — you’re still smiling.","modal":"must have laughed","canonicalFunction":"certainty/deduction","acceptedFunctions":["certainty/deduction"],"explanation":"Must have + past participle is a deduction about the past."},
{"id":"q2","sentence":"Can you keep a straight face during a joke?","modal":"Can","canonicalFunction":"ability","acceptedFunctions":["ability"],"explanation":"Can asks whether someone is able to do this."},
{"id":"q3","sentence":"You should watch that stand-up special; it’s hilarious.","modal":"should","canonicalFunction":"advice","acceptedFunctions":["advice"],"explanation":"Should recommends an action."},
{"id":"q4","sentence":"You mustn’t laugh during the serious scene.","modal":"mustn’t","canonicalFunction":"prohibition","acceptedFunctions":["prohibition"],"explanation":"Mustn’t says the action is not allowed."},
{"id":"q5","sentence":"It might be the funniest film of the year.","modal":"might","canonicalFunction":"probability/possibility","acceptedFunctions":["probability/possibility"],"explanation":"Might presents an uncertain possibility."},
{"id":"q6","sentence":"Can I tell you a joke?","modal":"Can","canonicalFunction":"permission","acceptedFunctions":["permission"],"explanation":"The speaker is asking permission to tell the joke."},
{"id":"q7","sentence":"I could juggle three balls when I was ten.","modal":"could","canonicalFunction":"ability","acceptedFunctions":["ability"],"explanation":"Could describes general ability in the past."},
{"id":"q8","sentence":"He can’t have written that joke himself — it’s too clever.","modal":"can’t have written","canonicalFunction":"certainty/deduction","acceptedFunctions":["certainty/deduction"],"explanation":"Can’t have + past participle expresses a negative deduction about the past."},
{"id":"q9","sentence":"We used to watch comedies every Friday.","modal":"used to","canonicalFunction":"habit","acceptedFunctions":["habit"],"explanation":"Used to describes a repeated past habit."},
{"id":"q10","sentence":"I should have prepared my routine better — I forgot my lines.","modal":"should have prepared","canonicalFunction":"past regret","acceptedFunctions":["past regret"],"explanation":"Should have + past participle expresses regret about a past action."}
]$$::jsonb),
('humour-in-the-school-hall', 2, 'Humour in the School Hall', 'Choose a modal for each school comedy-night moment.', 'fill_modal', 20, 0, 'Medium', 20, 3,
'["can", "can’t", "could", "couldn’t", "may", "might", "must", "mustn’t", "should", "shouldn’t", "have to", "need to", "don’t have to", "needn’t", "would", "used to", "ought to"]'::jsonb,
$$[
{"id":"q1","before":"The school is organising a comedy night, so we ","after":" book the hall.","canonicalAnswer":"have to","acceptedAnswers":["have to","need to"],"function":"obligation","explanation":"The event makes booking the hall necessary."},
{"id":"q2","before":"You ","after":" bring your own snacks — there will be food there.","canonicalAnswer":"don’t have to","acceptedAnswers":["don’t have to","don't have to","don’t need to","don't need to","needn’t","needn't"],"function":"no obligation","explanation":"Food is provided, so bringing snacks is not necessary."},
{"id":"q3","before":"That joke was so funny — I ","after":" stop laughing!","canonicalAnswer":"couldn’t","acceptedAnswers":["couldn’t","couldn't","could not"],"function":"disability","explanation":"Couldn’t describes being unable to stop laughing in that past situation."},
{"id":"q4","before":"You ","after":" laugh at the teacher’s joke; it’s polite.","canonicalAnswer":"should","acceptedAnswers":["should","ought to","could"],"function":"advice","explanation":"Should, ought to, and could can make this polite recommendation."},
{"id":"q5","before":"The comedian looks nervous — he ","after":" be new to the stage.","canonicalAnswer":"must","acceptedAnswers":["must","might","may","could"],"function":"certainty/deduction","explanation":"Must is a strong deduction; the other accepted forms express possibility."},
{"id":"q6","before":"We ","after":" be late, or we’ll miss the first act.","canonicalAnswer":"mustn’t","acceptedAnswers":["mustn’t","mustn't","can’t","can't"],"function":"prohibition","explanation":"Mustn’t and can’t warn that being late is not allowed in this situation."},
{"id":"q7","before":"", "after":" you do any impressions of famous people?","canonicalAnswer":"Can","acceptedAnswers":["can"],"function":"ability","explanation":"Can asks about ability in general."},
{"id":"q8","before":"I ","after":" have recorded the show — it was amazing.","canonicalAnswer":"should","acceptedAnswers":["should"],"function":"past regret","explanation":"Should have + past participle expresses regret about not recording it."},
{"id":"q9","before":"She’s so serious; she ","after":" be the only one not laughing.","canonicalAnswer":"must","acceptedAnswers":["must","might","may","could"],"function":"certainty/deduction","explanation":"Must is the strongest deduction; the alternatives express possibility."},
{"id":"q10","before":"It’s cloudy — the outdoor show ","after":" be cancelled.","canonicalAnswer":"might","acceptedAnswers":["might","may","could"],"function":"probability/possibility","explanation":"All three modals can express an uncertain possibility."},
{"id":"q11","before":"When I was a kid, I ","after":" tell the same joke over and over.","canonicalAnswer":"would","acceptedAnswers":["would","used to"],"function":"habit","explanation":"Would and used to both describe a repeated past action here."},
{"id":"q12","before":"You ","after":" tell that joke in class — it’s inappropriate.","canonicalAnswer":"mustn’t","acceptedAnswers":["mustn’t","mustn't","shouldn’t","shouldn't"],"function":"prohibition","explanation":"Mustn’t prohibits the joke; shouldn’t advises against it."},
{"id":"q13","before":"", "after":" I ask you a quick question about the routine?","canonicalAnswer":"Can","acceptedAnswers":["can","could"],"function":"permission","explanation":"Can asks permission informally; could is more polite. May is not the natural register here."},
{"id":"q14","before":"He ","after":" have forgotten his lines; he looked confused.","canonicalAnswer":"might","acceptedAnswers":["might","may","must"],"function":"probability/possibility","explanation":"Might or may express a possibility; must would make a stronger deduction."},
{"id":"q15","before":"You ","after":" practise your timing if you want the joke to land.","canonicalAnswer":"should","acceptedAnswers":["should","ought to","could"],"function":"advice","explanation":"These forms can make a recommendation."},
{"id":"q16","before":"The audience ","after":" stop laughing — the comedian is that good.","canonicalAnswer":"can’t","acceptedAnswers":["can’t","can't","cannot"],"function":"disability","explanation":"Can’t stop laughing describes inability to stop in the present."},
{"id":"q17","before":"We ","after":" decide who will host the show tonight.","canonicalAnswer":"have to","acceptedAnswers":["have to","need to"],"function":"obligation","explanation":"The group needs to decide who will host."},
{"id":"q18","before":"I ","after":" do a funny accent, but it’s not very good.","canonicalAnswer":"can","acceptedAnswers":["can"],"function":"ability","explanation":"Can describes present ability."},
{"id":"q19","before":"They ","after":" be twins — they look identical and laugh the same way.","canonicalAnswer":"must","acceptedAnswers":["must","might","may","could"],"function":"certainty/deduction","explanation":"Must is a strong deduction from the evidence."},
{"id":"q20","before":"You ","after":" have told me the ending — now the film is ruined!","canonicalAnswer":"shouldn’t","acceptedAnswers":["shouldn’t","shouldn't","should not"],"function":"past regret","explanation":"Shouldn’t have + past participle criticises a past action."}
]$$::jsonb),
('the-stand-up-comedy-show', 2, 'A Paragraph: The Stand-Up Comedy Show', 'Complete the continuous paragraph, then review feedback for each gap.', 'paragraph', 5, 12, 'Medium', 12, 4,
'["had to", "could", "were able to", "mustn’t", "shouldn’t", "must", "might", "may", "couldn’t", "should", "have to", "need to", "didn’t have to", "should have", "must have"]'::jsonb,
$$[
{"id":"g1","before":"Last Saturday, our school organised a stand-up comedy show, and everyone ","after":" rehearse for weeks beforehand.","canonicalAnswer":"had to","acceptedAnswers":["had to","needed to"],"function":"obligation","explanation":"The narration is in the past, so have to becomes had to."},
{"id":"g2","before":" Students ","after":" choose any topic they liked, but the teachers said we ","canonicalAnswer":"could","acceptedAnswers":["could","were able to"],"function":"ability","explanation":"Could describes a past ability or opportunity; were able to is also possible for this completed choice."},
{"id":"g3","before":"", "after":" use hurtful jokes about anyone.","canonicalAnswer":"mustn’t","acceptedAnswers":["mustn’t","mustn't","shouldn’t","shouldn't"],"function":"prohibition","explanation":"Mustn’t sets the rule; shouldn’t gives advice against hurtful jokes."},
{"id":"g4","before":" On the night, the hall was packed, and the first comedian looked terrified — she ","after":" have been very nervous.","canonicalAnswer":"must","acceptedAnswers":["must","might","may","could"],"function":"certainty/deduction","explanation":"Must is the strongest deduction from her visible fear."},
{"id":"g5","before":" Her opening joke was slow, but by the third minute the audience ","after":" stop laughing.","canonicalAnswer":"couldn’t","acceptedAnswers":["couldn’t","couldn't","could not"],"function":"disability","explanation":"Couldn’t describes being unable to stop laughing in the past."},
{"id":"g6","before":" Halfway through, someone forgot their lines, but the host said, ‘Don’t worry — you ","after":" just improvise!’","canonicalAnswer":"should","acceptedAnswers":["should","could"],"function":"advice","explanation":"Should gives advice; could is also a possible suggestion."},
{"id":"g7","before":" The comedian ","after":" have felt embarrassed at first, but she turned the mistake into the funniest moment of the night.","canonicalAnswer":"might","acceptedAnswers":["might","may","could"],"function":"probability/possibility","explanation":"Might, may, and could express a possibility about her past feelings."},
{"id":"g8","before":" After the show, our teacher told us we ","after":" write a report if we didn’t want to, but we ","canonicalAnswer":"didn’t have to","acceptedAnswers":["didn’t have to","didn't have to","did not have to"],"function":"no obligation","explanation":"The teacher told us in the past, so use didn’t have to."},
{"id":"g9","before":"", "after":" thank the organisers.","canonicalAnswer":"should","acceptedAnswers":["should","ought to"],"function":"advice","explanation":"Should or ought to recommends thanking them."},
{"id":"g10","before":" I think everyone ","after":" have agreed that it was the best school event of the year.","canonicalAnswer":"must","acceptedAnswers":["must","might","may","could"],"function":"certainty/deduction","explanation":"Must is the strongest conclusion; might, may, and could express less certainty."},
{"id":"g11","before":" Next time, I ","after":" even perform myself — but first, I ","canonicalAnswer":"might","acceptedAnswers":["might","may"],"function":"probability/possibility","explanation":"Might and may express a possible future choice."},
{"id":"g12","before":"", "after":" practise my jokes!","canonicalAnswer":"have to","acceptedAnswers":["have to","need to"],"function":"obligation","explanation":"Have to and need to express necessary preparation."}
]$$::jsonb),
('past-modals-and-regrets', 2, 'Past Modals & Regrets', 'Use a past modal to infer, regret, or describe an unrealised possibility.', 'fill_modal', 10, 0, 'Hard', 10, 5,
'["must have", "can’t have", "couldn’t have", "should have", "shouldn’t have", "could have", "might have", "may have", "might not have", "may not have"]'::jsonb,
$$[
{"id":"q1","before":"You’re still smiling — you ","after":" the show.","canonicalAnswer":"must have enjoyed","acceptedAnswers":["must have enjoyed","might have enjoyed","may have enjoyed","could have enjoyed"],"function":"certainty/deduction","explanation":"Must have enjoyed is a strong deduction; might, may, and could have express possibility."},
{"id":"q2","before":"I ","after":" that joke — nobody laughed.","canonicalAnswer":"shouldn’t have told","acceptedAnswers":["shouldn’t have told","shouldn't have told","should not have told"],"function":"past regret","explanation":"Shouldn’t have + past participle criticises a past choice."},
{"id":"q3","before":"She ","after":" the comedy contest, but she got sick.","canonicalAnswer":"could have won","acceptedAnswers":["could have won","might have won"],"function":"past regret","explanation":"Could have won describes an unrealised possibility."},
{"id":"q4","before":"He looks confused — he ","after":" the punchline.","canonicalAnswer":"might not have understood","acceptedAnswers":["might not have understood","may not have understood"],"function":"probability/possibility","explanation":"Might not have and may not have express uncertainty about a past event."},
{"id":"q5","before":"They ","after":" already — their coats are still here.","canonicalAnswer":"can’t have left","acceptedAnswers":["can’t have left","can't have left","cannot have left","couldn’t have left","couldn't have left"],"function":"certainty/deduction","explanation":"Can’t have + past participle expresses a negative deduction."},
{"id":"q6","before":"We ","after":" more before the performance.","canonicalAnswer":"should have practised","acceptedAnswers":["should have practised","ought to have practised","could have practised"],"function":"past regret","explanation":"Should have practised expresses regret; could have practised describes an available but unused possibility."},
{"id":"q7","before":"The comedian ","after":" his lines — he kept pausing.","canonicalAnswer":"must have forgotten","acceptedAnswers":["must have forgotten","might have forgotten","may have forgotten","could have forgotten"],"function":"certainty/deduction","explanation":"Must have forgotten is the strongest deduction; the alternatives express possibility."},
{"id":"q8","before":"I ","after":" a better joke, but I was too shy.","canonicalAnswer":"could have told","acceptedAnswers":["could have told","might have told"],"function":"past regret","explanation":"Could have told describes an unrealised opportunity."},
{"id":"q9","before":"You ","after":" at his mistake — it was cruel.","canonicalAnswer":"shouldn’t have laughed","acceptedAnswers":["shouldn’t have laughed","shouldn't have laughed","should not have laughed"],"function":"past regret","explanation":"Shouldn’t have laughed criticises a past action."},
{"id":"q10","before":"The audience ","after":" the show — they gave a standing ovation.","canonicalAnswer":"must have loved","acceptedAnswers":["must have loved","might have loved","may have loved","could have loved"],"function":"certainty/deduction","explanation":"Must have loved is a strong deduction from the standing ovation."}
]$$::jsonb),
('mixed-review-modal-function', 2, 'Mixed Review: Modal + Function', 'Complete each sentence and name the modal’s function.', 'mixed', 20, 0, 'Hard', 40, 6, NULL,
$$[
{"id":"q1","before":"You ","after":" be joking!","canonicalAnswer":"must","acceptedAnswers":["must"],"canonicalFunction":"certainty/deduction","acceptedFunctions":["certainty/deduction"],"explanation":"Must is a strong deduction about what is happening."},
{"id":"q2","before":"", "after":" you speak in public without panicking?","canonicalAnswer":"Can","acceptedAnswers":["can"],"canonicalFunction":"ability","acceptedFunctions":["ability"],"explanation":"Can asks about ability."},
{"id":"q3","before":"We ","after":" leave before the last act.","canonicalAnswer":"have to","acceptedAnswers":["have to","need to"],"canonicalFunction":"obligation","acceptedFunctions":["obligation"],"explanation":"Have to and need to express necessity."},
{"id":"q4","before":"The theatre rules say: You ","after":" laugh during the serious scene.","canonicalAnswer":"mustn’t","acceptedAnswers":["mustn’t","mustn't","can’t","can't","cannot"],"canonicalFunction":"prohibition","acceptedFunctions":["prohibition"],"explanation":"The stated rule makes laughing prohibited."},
{"id":"q5","before":"", "after":" I borrow your comedy DVD?","canonicalAnswer":"Can","acceptedAnswers":["can","could"],"canonicalFunction":"permission","acceptedFunctions":["permission"],"explanation":"Can asks permission informally; could is a polite alternative. May is rejected here because this is an informal situation."},
{"id":"q6","before":"You ","after":" watch that show — it’s brilliant.","canonicalAnswer":"should","acceptedAnswers":["should"],"canonicalFunction":"advice","acceptedFunctions":["advice"],"explanation":"Should recommends watching the show."},
{"id":"q7","before":"It ","after":" rain on the day of the outdoor show.","canonicalAnswer":"might","acceptedAnswers":["might","may","could"],"canonicalFunction":"probability/possibility","acceptedFunctions":["probability/possibility"],"explanation":"These modals all express an uncertain possibility."},
{"id":"q8","before":"I ","after":" a photo of the comedian.","canonicalAnswer":"should have taken","acceptedAnswers":["should have taken"],"canonicalFunction":"past regret","acceptedFunctions":["past regret"],"explanation":"Should have + past participle expresses regret about not taking the photo."},
{"id":"q9","before":"He ","after":" be the funniest person in our class.","canonicalAnswer":"must","acceptedAnswers":["must"],"canonicalFunction":"certainty/deduction","acceptedFunctions":["certainty/deduction"],"explanation":"Must expresses the speaker’s strong deduction."},
{"id":"q10","before":"She ","after":" the punchline; we don’t know yet, but it’s one possible explanation.","canonicalAnswer":"might have forgotten","acceptedAnswers":["might have forgotten","may have forgotten","could have forgotten"],"canonicalFunction":"probability/possibility","acceptedFunctions":["probability/possibility"],"explanation":"Might, may, and could have express a possible past explanation; must have would instead be a deduction."},
{"id":"q11","before":"When I was young, I ","after":" laugh at everything.","canonicalAnswer":"would","acceptedAnswers":["would","used to"],"canonicalFunction":"habit","acceptedFunctions":["habit"],"explanation":"Would and used to describe a repeated past action here."},
{"id":"q12","before":"", "after":" you help me write a joke?","canonicalAnswer":"Could","acceptedAnswers":["could","can"],"canonicalFunction":"request","acceptedFunctions":["request"],"explanation":"Could and can ask someone to do something; could is more polite."},
{"id":"q13","before":"You ","after":" bring a costume — it’s optional.","canonicalAnswer":"don’t have to","acceptedAnswers":["don’t have to","don't have to","don’t need to","don't need to","needn’t","needn't"],"canonicalFunction":"no obligation","acceptedFunctions":["no obligation"],"explanation":"The costume is optional, so bringing one is not necessary."},
{"id":"q14","before":"They ","after":" have practised — the timing was perfect.","canonicalAnswer":"must","acceptedAnswers":["must"],"canonicalFunction":"certainty/deduction","acceptedFunctions":["certainty/deduction"],"explanation":"Must have + past participle is a deduction from the perfect timing."},
{"id":"q15","before":"The school rules say: You ","after":" tell that joke in front of the teacher.","canonicalAnswer":"mustn’t","acceptedAnswers":["mustn’t","mustn't","can’t","can't","cannot"],"canonicalFunction":"prohibition","acceptedFunctions":["prohibition"],"explanation":"The rule says the joke is not allowed."},
{"id":"q16","before":"I ","after":" do a French accent, but not a Moroccan one.","canonicalAnswer":"can","acceptedAnswers":["can"],"canonicalFunction":"ability","acceptedFunctions":["ability"],"explanation":"Can describes present ability."},
{"id":"q17","before":"", "after":" I ask you something funny?","canonicalAnswer":"Can","acceptedAnswers":["can","could"],"canonicalFunction":"permission","acceptedFunctions":["permission"],"explanation":"Can asks permission informally; could is polite. May is rejected in this informal context."},
{"id":"q18","before":"The audience ","after":" have loved the show — they clapped for ten minutes.","canonicalAnswer":"must","acceptedAnswers":["must"],"canonicalFunction":"certainty/deduction","acceptedFunctions":["certainty/deduction"],"explanation":"Must is the strong deduction supported by the standing ovation."},
{"id":"q19","before":"You ","after":" have warned me — I was so embarrassed!","canonicalAnswer":"should","acceptedAnswers":["should"],"canonicalFunction":"past regret","acceptedFunctions":["past regret"],"explanation":"Should have warned expresses criticism or regret about a past action."},
{"id":"q20","before":"We ","after":" rehearse tomorrow at four.","canonicalAnswer":"have to","acceptedAnswers":["have to","need to"],"canonicalFunction":"obligation","acceptedFunctions":["obligation"],"explanation":"Rehearsing is necessary before the show."}
]$$::jsonb)
